@namespace sv_afa32b0ff84f4f7baa9319bff1f006fd.Components.Pages.Settings

<nav class="settings-nav">
    <h3 class="settings-nav-title">Settings</h3>
    <ul class="settings-nav-list">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                @section
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };
}

@namespace sv_afa32b0ff84f4f7baa9319bff1f006fd.Components.Pages.Settings
@using sv_afa32b0ff84f4f7baa9319bff1f006fd.Services

<div class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-preview">
        <img src="@AvatarUrl" alt="Avatar" class="avatar-image" />
        <p class="avatar-url">@AvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="DisplayName" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="Email" class="form-control" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="Bio" class="form-control" rows="4"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveChanges">Save Changes</button>
        <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
    </div>

    @if (!string.IsNullOrEmpty(_statusMessage))
    {
        <div class="toast-message success">@_statusMessage</div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName { get; set; } = "";
    private string Email { get; set; } = "";
    private string AvatarUrl { get; set; } = "";
    private string Bio { get; set; } = "";
    private string? _statusMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && _statusMessage is null)
        {
            LoadFromProfile(Profile);
        }
    }

    private void LoadFromProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        AvatarUrl = profile.AvatarUrl;
        Bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        _statusMessage = "Profile saved successfully!";
        StateHasChanged();
        _ = ClearMessageAfterDelay();
    }

    private void DiscardChanges()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        _statusMessage = null;
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _statusMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_afa32b0ff84f4f7baa9319bff1f006fd.Components.Pages.Settings
@using sv_afa32b0ff84f4f7baa9319bff1f006fd.Services

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="EmailNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            Email Notifications
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="PushNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            Push Notifications
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="WeeklyDigest" class="toggle-input" />
            <span class="toggle-switch"></span>
            Weekly Digest
        </label>
    </div>

    <div class="channels-section">
        <h3>Muted Channels</h3>
        @foreach (var channel in AvailableChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@MutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                @channel
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SavePreferences">Save Preferences</button>
    </div>

    @if (!string.IsNullOrEmpty(_statusMessage))
    {
        <div class="toast-message success">@_statusMessage</div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();
    private string? _statusMessage;

    private static readonly string[] AvailableChannels = { "general", "marketing", "engineering", "announcements", "random" };

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        _statusMessage = "Preferences saved!";
        StateHasChanged();
        _ = ClearMessage();
    }

    private async Task ClearMessage()
    {
        await Task.Delay(3000);
        _statusMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_afa32b0ff84f4f7baa9319bff1f006fd.Components.Pages.Settings
@using sv_afa32b0ff84f4f7baa9319bff1f006fd.Services

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(_passwordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (_passwordPanelOpen)
        {
            <div class="panel-content">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
                </div>
                @if (!string.IsNullOrEmpty(_passwordError))
                {
                    <div class="error-message">@_passwordError</div>
                }
                @if (!string.IsNullOrEmpty(_passwordSuccess))
                {
                    <div class="toast-message success">@_passwordSuccess</div>
                }
                <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="twofa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" checked="@TwoFactorEnabled" @onchange="Toggle2FA" class="toggle-input" />
                <span class="toggle-switch"></span>
                <span>Two-Factor Authentication</span>
                <span class="status-indicator @(TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </label>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
            <p class="info-text">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @if (Settings?.Sessions is not null)
                {
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="dialog-overlay" @onclick="CancelRevoke">
            <div class="dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="ExecuteRevoke">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<bool> OnToggle2FA { get; set; }

    private string CurrentSessionId => Settings?.Sessions?.FirstOrDefault()?.Id ?? "";

    private bool TwoFactorEnabled => Settings?.TwoFactorEnabled ?? false;

    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private string? _passwordSuccess;
    private ActiveSession? _sessionToRevoke;

    private async Task UpdatePassword()
    {
        _passwordError = null;
        _passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _passwordSuccess = "Password updated successfully!";
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private async Task Toggle2FA(ChangeEventArgs e)
    {
        var enabled = (bool)(e.Value ?? false);
        await OnToggle2FA.InvokeAsync(enabled);
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ExecuteRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@namespace sv_afa32b0ff84f4f7baa9319bff1f006fd.Components.Pages.Settings
@using sv_afa32b0ff84f4f7baa9319bff1f006fd.Services

<div class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme Selector -->
    <div class="form-group">
        <h3>Theme</h3>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-label">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(Theme == theme)"
                           @onchange="() => Theme = theme" />
                    @theme
                </label>
            }
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <h3>Font Size</h3>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(FontSize == size)"
                           @onchange="() => FontSize = size" />
                    @size
                </label>
            }
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="Language" class="form-control">
            @foreach (var lang in Languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <!-- Compact Mode Toggle -->
    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="CompactMode" class="toggle-input" />
            <span class="toggle-switch"></span>
            Compact Mode
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Preview</h4>
        <p class="preview-text">This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>A preview of the interface with your chosen theme, font size, and layout.</p>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
    </div>

    @if (!string.IsNullOrEmpty(_statusMessage))
    {
        <div class="toast-message success">@_statusMessage</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "Light";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }
    private string? _statusMessage;

    private static readonly string[] Languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{Theme.ToLowerInvariant()} preview-font-{FontSize.ToLowerInvariant()}";
        if (CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        _statusMessage = "Appearance saved!";
        StateHasChanged();
        _ = ClearMessage();
    }

    private async Task ClearMessage()
    {
        await Task.Delay(3000);
        _statusMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

