@namespace sv_afa32b0ff84f4f7baa9319bff1f006fd.Components.Pages.Settings
@using sv_afa32b0ff84f4f7baa9319bff1f006fd.Services

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="EmailNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            Email Notifications
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="PushNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            Push Notifications
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="WeeklyDigest" class="toggle-input" />
            <span class="toggle-switch"></span>
            Weekly Digest
        </label>
    </div>

    <div class="channels-section">
        <h3>Muted Channels</h3>
        @foreach (var channel in AvailableChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@MutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                @channel
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SavePreferences">Save Preferences</button>
    </div>

    @if (!string.IsNullOrEmpty(_statusMessage))
    {
        <div class="toast-message success">@_statusMessage</div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();
    private string? _statusMessage;

    private static readonly string[] AvailableChannels = { "general", "marketing", "engineering", "announcements", "random" };

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        _statusMessage = "Preferences saved!";
        StateHasChanged();
        _ = ClearMessage();
    }

    private async Task ClearMessage()
    {
        await Task.Delay(3000);
        _statusMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

